$ErrorActionPreference='Stop'
$here=$PSScriptRoot;$repo=Split-Path $here -Parent;$root=Join-Path ([IO.Path]::GetTempPath()) ('maya-staging-reconcile-'+[guid]::NewGuid().ToString('N'))
Import-Module (Join-Path $here 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $here 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $here 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $here 'Repato.MayaQaRunnerRepair.psm1') -Force -WarningAction SilentlyContinue
function Reject($name,[scriptblock]$action){$rejected=$false;try{&$action|Out-Null}catch{$rejected=$true};if(!$rejected){throw "Unsafe staging reconciliation accepted: $name"}}
try {
 New-Item -ItemType Directory $root|Out-Null;$b=New-MayaQaBootstrap -StoreRoot $root -QaWorkflowId 'create-plan-views-v1' -RunId ([guid]::NewGuid().ToString('N'));$taskId=$b.TaskId;$workflowId=$b.WorkflowId;$buildId='build-synthetic';$commit='A'*40;$request=[guid]::NewGuid().ToString('N');$payload='3007A4A0C23FE2FAED707FB27888A8F42DE9D9DA9B9A06948EA1AFB37F858B85';$seen=[DateTimeOffset]::UtcNow.ToString('O');$ledger=Join-Path $root 'replay.json';$deployed=Join-Path $root 'Repato.Revit.dll';$runner=Join-Path $root 'Repato.CreatePlanViews.TestRunner.addin';$sourceRunner=Join-Path $repo 'QA\Repato.CreatePlanViews.TestRunner.addin';Copy-Item $sourceRunner $runner;Set-Content $deployed 'synthetic candidate';$candidateHash=(Get-FileHash $deployed -Algorithm SHA256).Hash;$runnerHash=(Get-FileHash $runner -Algorithm SHA256).Hash
 $receipt=[pscustomobject]@{RequestId=$request;RunId=$request;PayloadHash=$payload;SeenUtc=$seen;AuthenticatedRequestBinding=$true;TaskId=$taskId;WorkflowId=$workflowId};@($receipt)|ConvertTo-Json -Compress|Set-Content -LiteralPath $ledger
 $null=Invoke-RepatoStoreMutation $root {param($d,$p)$t=Find-RepatoTask $d $taskId;$t.status='awaiting-approval';$t.workflowStage='approval';$t.approvalRequests=@([pscustomobject]@{requestId=[guid]::NewGuid().ToString('N');action='qa-run';status='pending';requiredLevel='user'});$w=@($t.deploymentWorkflows|Where-Object workflowId -ceq $workflowId)[0];$w|Add-Member NoteProperty qaBuildRequest ([pscustomobject]@{BuildRequestId=$buildId}) -Force;$w|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$w|Add-Member NoteProperty qaBuildEvidence ([pscustomobject]@{BuildRequestId=$buildId;EvidenceSource='FrozenCandidate';CandidateSourceCommit=$commit;ArtifactSha256=$candidateHash;RunnerManifestSha256=$runnerHash;DeploymentValidation=$false}) -Force;$t}
 $args=@{StoreRoot=$root;TaskId=$taskId;WorkflowId=$workflowId;BuildRequestId=$buildId;QaWorkflowId='create-plan-views-v1';TestId='create-plan-views-v1';CandidateSourceCommit=$commit;CandidateSha256=$candidateHash;RequestId=$request;PayloadHash=$payload;ExpectedSeenUtc=$seen;LedgerPath=$ledger;DeployedDllPath=$deployed;RunnerManifestPath=$runner;RunnerManifestSha256=$runnerHash;RevitProcessProvider={@()}}
 Reject 'wrong payload identity' {Complete-MayaQaAmbiguousStagingReconciliation @args -PayloadHash ('F'*64)};Reject 'wrong receipt time' {Complete-MayaQaAmbiguousStagingReconciliation @args -ExpectedSeenUtc '2026-10-11T04:09:51Z'};Reject 'live Revit' {Complete-MayaQaAmbiguousStagingReconciliation @args -RevitProcessProvider {[pscustomobject]@{Id=1}}}
 @([pscustomobject]@{RequestId=$request;RunId=$request;PayloadHash=$payload;SeenUtc=$seen;AuthenticatedRequestBinding=$true;TaskId=$taskId;WorkflowId=$workflowId},[pscustomobject]@{RequestId=$request;RunId=$request;PayloadHash=$payload;SeenUtc=$seen;AuthenticatedRequestBinding=$true;TaskId=$taskId;WorkflowId=$workflowId})|ConvertTo-Json -Compress|Set-Content -LiteralPath $ledger;Reject 'non-unique receipt' {Complete-MayaQaAmbiguousStagingReconciliation @args};@($receipt)|ConvertTo-Json -Compress|Set-Content -LiteralPath $ledger
 $response=Complete-MayaQaAmbiguousStagingReconciliation @args;$task=Find-RepatoTask (Read-RepatoTaskStore $root) $args.TaskId;$audit=@($task.mayaQaStagingReconciliations|Where-Object RequestId -ceq $request)
 if(!$response.succeeded -or $response.candidateSha256 -ine $args.CandidateSha256 -or $response.taskId -cne $args.TaskId -or $response.reconciliationDisposition -cne 'ObservedAppliedResponseUnavailable'){throw 'Canonical staging response is invalid.'};if($audit.Count -ne 1 -or !$audit[0].RevitAbsent -or !$audit[0].ResponseUnavailable -or $audit[0].ResendPermitted){throw 'Ambiguous staging evidence was not preserved.'}
 Reject 'duplicate/reuse' {Complete-MayaQaAmbiguousStagingReconciliation @args}
 'Ambiguous staging reconciliation passed: canonical response, exact receipt/time/hash, deployed hashes, no-Revit, evidence persistence, and duplicate rejection'
} finally {if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force}}
